const item = $input.first();
let xml = '';

// 1. Buscar XML en json (string directo o cualquier propiedad)
if (typeof item.json === 'string') {
  xml = item.json;
} else if (item.json) {
  for (const val of Object.values(item.json)) {
    if (typeof val === 'string' && val.includes('<rss')) {
      xml = val;
      break;
    }
  }
}

// 2. Respaldo: buscar en binary si n8n v2 lo guardó como archivo
if (!xml && item.binary) {
  const binKey = Object.keys(item.binary)[0];
  if (binKey && item.binary[binKey]?.data) {
    xml = Buffer.from(item.binary[binKey].data, 'base64').toString('utf8');
  }
}

const items = [...xml.matchAll(/<item>[\s\S]*?<title>([\s\S]*?)<\/title>[\s\S]*?<pubDate>([\s\S]*?)<\/pubDate>/g)]
  .map(m => ({
    titulo: m[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim(),
    fecha: m[2].trim(),
    timestamp: new Date(m[2].trim()).getTime() || 0
  }))
  .sort((a, b) => b.timestamp - a.timestamp)
  .slice(0, 6)
  .map(({ titulo, fecha }) => ({ titulo, fecha }));

let temaBuscado = '';
try {
  temaBuscado = $('Webhook').first().json.body?.tema || '';
} catch {
  temaBuscado = '';
}

return [{
  json: {
    tema: temaBuscado,
    resumenPrincipal: items.length > 0
      ? items.map(i => `• ${i.titulo} (${i.fecha})`).join('\n')
      : 'Sin titulares recientes encontrados para este tema.',
    resultadosRelacionados: items,
    fuente: 'Google News RSS 2026'
  }
}];
